// Forwards any failed LendLoop execution to Convex so admins see it in the
// app (Admin > Automation problems) instead of only inside n8n.
// Only metadata is sent: no input data from the failed run.
const crypto = require('crypto');
const { execution = {}, workflow = {}, trigger } = $input.first().json;
const err = execution.error || (trigger && trigger.error) || {};
const body = JSON.stringify({
  executionId: String(execution.id || `trigger-${workflow.id}-${Date.now()}`),
  workflowName: String(workflow.name || 'unknown workflow'),
  nodeName: execution.lastNodeExecuted ? String(execution.lastNodeExecuted) : undefined,
  message: String(err.message || 'Unknown error').slice(0, 1000),
});
const path = '/n8n/workflow-errors';
const ts = String(Date.now());
const sig = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_HMAC_SECRET).update(`${ts}.POST ${path}.${body}`).digest('hex');
return [{ json: { url: $env.CONVEX_SITE_URL + path, ts, sig, body } }];
